    [5753] = {
        achievementId = 5753,
        name = "Cataclysmically Delicious",
        category = "Exploration",
        sourceType = "Achievement",
        source = "Cataclysmically Delicious",
        difficulty = "medium",
        difficultyReason = "Eat forty-eight distinct foods; vendor shopping plus twenty-six cooked dishes.",
        acquisition = "Difficulty: Medium - Eat forty-eight distinct foods; vendor shopping plus twenty-six cooked dishes.\n\n1. Track the forty-eight current criteria and buy ONE edible serving of every missing food. You must EAT each, not merely learn its recipe, cook it, or hold it in your bags. Finished tradeable foods can be bought on the Auction House or supplied by another cook, so Cooking is optional for this achievement. Current item names differ from some old comments; use the names below.\n\n2. ALLIANCE CAPITAL SHOPPING: Innkeeper Allison in Stormwind Trade District (60.4,75.2) sells Buttery Wheat Roll, Pine Nut Bread, Sour Green Apple and Highland Pomegranate. Maegan Tillman in the Old Town inn (75.2,54.6) sells Violet Morel and Scarlet Polypore. Buy only missing entries and eat each to confirm the checkmark.\n\n3. HORDE CAPITAL SHOPPING: Innkeeper Gryshka (53.4,78.8) sells Buttery Wheat Roll, Pine Nut Bread, Roasted Beef and Massive Turkey Leg. Batamsi in the Valley of Spirits (32.2,69.6) sells Sliced Raw Billfish, Grilled Shark, Sour Green Apple and Highland Pomegranate; Jin'diza nearby (32.2,65.0) sells Hardtack. Kor'jus, the city's mushroom vendor, supplies Violet Morel and Scarlet Polypore; ask a guard for the appropriate city district if needed.\n\n4. TWILIGHT HIGHLANDS ALLIANCE: at Highbank, Innkeeper Teresa (79.0,77.6) sells Gilnean White, Highland Sheep Cheese, Smoked String Cheese and Hardtack. Nearby cook Evan Silvia (78.4,76.6) sells Grilled Shark, Sliced Raw Billfish, Roasted Beef, Massive Turkey Leg, Simmered Squid and Stewed Rabbit. Innkeeper Francis (79.4,78.4) sells Tropical Sunfruit. This fills foods not supplied by the Stormwind stop.\n\n5. TWILIGHT HIGHLANDS HORDE: Lizzy 'Lemons' in Dragonmaw Port (76.2,52.6) sells Gilnean White, Highland Sheep Cheese, Smoked String Cheese, Tropical Sunfruit and Stewed Rabbit, plus several foods already available in Orgrimmar. For Simmered Squid, use Kazemde in Ramkahen, original Uldum (54.6,32.8), who also sells Grilled Shark, Sliced Raw Billfish and Hardtack if you missed them. Use Zidormi's earlier Uldum when necessary.\n\n6. BOTH FACTIONS: buy Rock-Hard Biscuit, Vile Purple Fungus, Oily Giblets and Unidentifiable Meat Dish from Gronk Hamcheeks beside the Crucible of Carnage grill (50.4,58.4). Use this merchant instead of the phased-out Hyjal vendors mentioned in launch comments. At Nordrassil in Mount Hyjal, Sebelia (63.0,24.0) sells Tasty Puffball. You should now have all TWENTY-TWO vendor foods checked.\n\n7. For the remaining TWENTY-SIX cooked foods, buy finished servings from the Auction House or a cook. If making them, learn Cataclysm Cooking and its recipes: Jon Casper near Stormwind's Robby Flay or Shazdar near Orgrimmar's Marogg sells recipes for Epicurean's Awards. Earn awards from the city Cooking dailies. Trainer-taught Blackened Surprise is separate from the purchased recipes.\n\n8. FISH DISHES, FIRST HALF: eat Baked Rockfish (Algaefin Rockfish), Blackbelly Sushi (Blackbelly Mudfish), Broiled Mountain Trout (Mountain Trout), Delicious Sagefish Tail (Deepsea Sagefish), Fish Fry (three Sharptooth), Lavascale Fillet and Lavascale Minestrone (one Lavascale Catfish each). Buy the finished foods if the recipe cost exceeds your interest in leveling Cooking.\n\n9. FISH DISHES, SECOND HALF: eat Lightly Fried Lurker and Lurker Lunch (one Striped Lurker each), Mushroom Sauce Mudfish (Blackbelly Mudfish), Pickled Guppy (Highland Guppy), Scalding Murglesnout (three Murglesnout), Severed Sagefish Head (Deepsea Sagefish) and Skewered Eel (Fathom Eel). The Limnologist/Oceanographer routes identify the corresponding freshwater/coastal catches.\n\n10. MEAT / SEAFOOD DISHES: eat Basilisk Liverdog (Basilisk 'Liver'), Beer-Basted Crocolisk and Crocolisk Au Gratin (one Crocolisk Tail each), Blackened Surprise (Toughened Flesh), Grilled Dragon (Dragon Flank), Hearty Seafood Soup and Whitecrest Gumbo (one Blood Shrimp each), Salted Eye (Snake Eye), Seasoned Crab (Monstrous Claw) and Tender Baked Turtle (Giant Turtle Tongue). These are ten DIFFERENT foods, even where two share an ingredient. Buy ingredients or the finished dish rather than following obsolete phased Hyjal creature farms.\n\n11. BAKING: eat Chocolate Cookie (Simple Flour plus Cocoa Beans) and Fortune Cookie (Simple Flour plus a Mysterious Fortune Card from Inscription or the Auction House). The award vendors sell Imported Supplies containing Cocoa Beans. Buying or consuming an ordinary Mysterious Fortune Card does not substitute for eating the cooked Fortune Cookie.\n\n12. Inspect all FORTY-EIGHT checkmarks and consume any missing exact name. Do not substitute a feast or a similar-level food. Cataclysmic Gourmet is a separate COOKING checklist; Cataclysmically Delicious needs eating and includes vendor foods that are not craftable.",
        stepCount = 12,
        waypoints = {
            { mapID = 84, x = 0.604, y = 0.752, step = 2, label = "Allison - bread / fruit" },
            { mapID = 84, x = 0.752, y = 0.546, step = 2, label = "Maegan Tillman - Violet Morel / Scarlet Polypore" },
            { mapID = 85, x = 0.534, y = 0.7879999999999999, step = 3, label = "Gryshka - bread / meat" },
            { mapID = 85, x = 0.322, y = 0.696, step = 3, label = "Batamsi - fish / fruit" },
            { mapID = 85, x = 0.322, y = 0.65, step = 3, label = "Jin'diza - Hardtack" },
            { mapID = 241, x = 0.79, y = 0.7759999999999999, step = 4, label = "Alliance: Teresa - cheese / Hardtack" },
