    [5755] = {
        achievementId = 5755,
        name = "Thirty Tabards",
        category = "Collections",
        sourceType = "Achievement",
        source = "Thirty Tabards",
        difficulty = "medium",
        difficultyReason = "Collect thirty distinct tabard appearances, with several reputation unlocks.",
        stepCount = 6,
        acquisition = "Difficulty: Medium - Collect thirty distinct tabard appearances, with several reputation unlocks.\n\n1. Track Thirty Tabards and inspect the tabard section of your appearance collection. Learn missing tabards by equipping them or otherwise completing their collection binding. Buying duplicate copies or merely previewing an appearance does not add another distinct tabard.\n\n2. Start with your faction's seven city tabards and the ordinary Guild Tabard. Visit each city's quartermaster near its flight master; Alliance uses Stormwind, Ironforge, Darnassus, Exodar, Gnomeregan, Gilneas and Tushui, while Horde uses Orgrimmar, Undercity, Thunder Bluff, Silvermoon, Darkspear, Bilgewater and Huojin. Use a city's earlier phase where its old quartermaster requires it.\n\n3. At Friendly and Honored with your guild, add Illustrious Guild Tabard and Renowned Guild Tabard from a guild vendor. These are different appearances from the ordinary Guild Tabard. Stormwind's Shay Pressler and Orgrimmar's Goram sell the guild rewards.\n\n4. Add the four Northrend championing tabards at Friendly: Argent Crusade, Kirin Tor, Wyrmrest Accord and Knights of the Ebon Blade. Then unlock the Cataclysm Friendly tabards for Ramkahen, Guardians of Hyjal, Earthen Ring, Therazane and your faction's Wildhammer/Dragonmaw clan. Complete Deepholm's storyline to reach Therazane's quartermaster.\n\n5. Fill the remaining slots from reputations you already have at Exalted, such as Cenarion Expedition, Lower City, Sha'tar, Consortium, Sporeggar, Keepers of Time and Shattered Sun. Obtain each DIFFERENT tabard and learn its appearance. Pandaria and later faction tabards provide alternatives; old reports that later-expansion tabards never count predate fixes.\n\n6. Collect the Tabard of the Explorer if you have World Explorer and the Tabard of the Achiever after Twenty-Five Tabards. These can help close the final gap. Check that the appearance has stayed learned before discarding any refundable purchase; stop when the live achievement counter reaches thirty.",
        waypoints = {
            { mapID = 84, x = 0.6459999999999999, y = 0.768, step = 3, label = "Shay Pressler - guild tabards" },
            { mapID = 85, x = 0.48200000000000004, y = 0.7559999999999999, step = 3, label = "Goram - guild tabards" },
            { mapID = 249, x = 0.54, y = 0.332, step = 4, label = "Abasi - Ramkahen tabard" },
            { mapID = 207, x = 0.573, y = 0.125, step = 4, label = "Therazane's Throne - after Deepholm campaign" },
        },
        sources = {
            "https://www.wowhead.com/achievement=5755#comments:id=1682919",
            "https://www.wowhead.com/achievement=5755#comments:id=2448651",
            "https://www.wowhead.com/achievement=5755#comments:id=2528997",
        },
        tips = "The collection became account-wide with wardrobe tracking. The old insistence on one character and the obsolete listing macros do not describe the current appearance counter. Retired event and old Gladiator tabards are unnecessary.",
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5755",
        sourceURL = "https://www.wowhead.com/achievement=5755#comments",
    },
    [5759] = {
