    [5762] = {
        achievementId = 5762,
        name = "Ohganot So Fast!",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Ohganot So Fast!",
        difficulty = "easy",
        difficultyReason = "Kill Mandokir while leaving his raptor Ohgan alive.",
        stepCount = 3,
        acquisition = "Difficulty: Easy - Kill Mandokir while leaving his raptor Ohgan alive.\n\n1. Enter Zul'Gurub on Heroic and go to Bloodlord Mandokir in the southeastern arena. Disable area damage and cleaving pets that might kill Ohgan.\n\n2. At a high Retail level, kill Mandokir directly with single-target damage before Ohgan needs handling. Do not attack the raptor: the achievement requires the boss to die without Ohgan dying.\n\n3. In a longer fight, slow or stun Ohgan while focusing Mandokir, avoid Devastating Slam and let the chained spirits handle encounter resurrections. Keeping the raptor controlled preserves the available spirits for longer, but killing it fails this objective.",
