    [5768] = {
        achievementId = 5768,
        name = "Heroic: Zul'Gurub",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: Zul'Gurub",
        difficulty = "easy",
        difficultyReason = "A high-level legacy clear; follow the dungeon's progression events and final-boss requirement.",
        stepCount = 5,
        acquisition = "Difficulty: Easy - A high-level legacy clear; follow the dungeon's progression events and final-boss requirement.\n\n1. Set Dungeon Difficulty to Heroic before entering Zul'Gurub. A different difficulty or a similarly named raid is not the requested clear.\n\n2. Enter the current Heroic five-player dungeon in Northern Stranglethorn. Defeat High Priest Venoxis and the other guardians you still need: Bloodlord Mandokir, High Priestess Kilnara and Zanzil. The optional Cache of Madness bosses are separate.\n\n3. Before fighting Jin'do, kill a Gurubashi Spirit Warrior on the lower terrace so its spirit will be available later. Start Jin'do on the upper platform and bring him into his spirit phase.\n\n4. In the spirit realm, bring the large Gurubashi Spirit onto the upper platform. Stand on a shielded Hakkar's Chain when the spirit targets you for Body Slam; let the slam break the chain's immunity shield, then kill the exposed chain. Repeat for all THREE chains while clearing small spirits and avoiding Shadow Spike.\n\n5. Let Hakkar's final sequence finish and check Jin'do's encounter credit. Attacking immune chains without breaking their shields does not complete the dungeon, regardless of your level.",
        waypoints = {
            {
                mapID = 50,
                x = 0.721,
                y = 0.32899999999999996,
                step = 1,
                label = "Zul'Gurub - Heroic dungeon entrance",
                mapName = "Northern Stranglethorn",
            },
            { mapID = 337, x = 0.509, y = 0.537, step = 2, label = "Venoxis - guardian", mapName = "Zul'Gurub" },
            { mapID = 337, x = 0.604, y = 0.799, step = 2, label = "Mandokir - guardian", mapName = "Zul'Gurub" },
            { mapID = 337, x = 0.48, y = 0.2, step = 2, label = "Kilnara - guardian", mapName = "Zul'Gurub" },
            {
                mapID = 337,
                x = 0.48503,
                y = 0.39521,
                step = 4,
                label = "Jin'do - break shields, then destroy three chains",
                mapName = "Zul'Gurub",
            },
        },
        sources = {
            "https://www.wowhead.com/achievement=5768#comments:id=1615610",
            "https://www.wowhead.com/achievement=5768#comments:id=5268713",
        },
        sourceComments = { 1615610, 5268713 },
        wowheadUrl = "https://www.wowhead.com/achievement=5768",
        sourceURL = "https://www.wowhead.com/achievement=5768#comments",
    },
    [5769] = {
        achievementId = 5769,
        name = "Heroic: Zul'Aman",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: Zul'Aman",
        difficulty = "easy",
        difficultyReason = "A high-level legacy clear; follow the dungeon's progression events and final-boss requirement.",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A high-level legacy clear; follow the dungeon's progression events and final-boss requirement.\n\n1. Set Dungeon Difficulty to Heroic before entering Zul'Aman. A different difficulty or a similarly named raid is not the requested clear.\n\n2. Select legacy Quel'Thalas with Zidormi at Thalassian Pass, then enter the original Ghostlands dungeon at 81.5,64.4. Speak to Vol'jin and complete the gong interaction to open the gate. Midnight's outdoor Zul'Aman is not this instance.\n\n3. Defeat the four animal bosses: Akil'zon, Nalorakk, Jan'alai and Halazzi. If also doing Bear-ly Made It, use that order and finish within the rescue timer; the ordinary completion achievement does not need the timed rescue.\n\n4. Continue to Hex Lord Malacrass and defeat him, then proceed to Daakara and kill him. Daakara replaced the old raid's Zul'jin and is the final boss for Heroic: Zul'Aman.",
        waypoints = {
            {
                mapID = 23,
                x = 0.5379999999999999,
                y = 0.087,
                step = 1,
                label = "Zidormi - select legacy Quel'Thalas",
                mapName = "Eastern Plaguelands",
            },
            { mapID = 95, x = 0.815, y = 0.644, step = 1, label = "Zul'Aman - legacy Heroic entrance", mapName = "Ghostlands" },
            { mapID = 333, x = 0.904, y = 0.529, step = 4, label = "Daakara - final boss", mapName = "Zul'Aman" },
        },
        sources = { "https://www.wowhead.com/achievement=5769#comments:id=1368266" },
        sourceComments = { 1368266 },
        wowheadUrl = "https://www.wowhead.com/achievement=5769",
        sourceURL = "https://www.wowhead.com/achievement=5769#comments",
    },
    [5779] = {
        achievementId = 5779,
        name = "You'll Feel Right as Rain",
        category = "Professions",
        sourceType = "Achievement",
        source = "You'll Feel Right as Rain",
        difficulty = "easy",
        difficultyReason = "Obtain ninety-one Chocolate Cookies and keep the stacking food buff active.",
        acquisition = "Difficulty: Easy - Obtain ninety-one Chocolate Cookies and keep the stacking food buff active.\n\n1. Obtain at least NINETY-ONE Chocolate Cookies (62680). Buy the finished cookies from another player or the Auction House, or learn the Cataclysm Cooking recipe and make them. You do not need Cooking if you buy the finished food.\n\n2. For the cooking route, buy Recipe: Chocolate Cookie from a Cataclysm sous-chef vendor for Epicurean's Awards. Make ninety-one cookies using ninety-one Simple Flour and ninety-one Cocoa Beans. The vendors sell bags of cocoa beans for awards; check the bag's quantity before buying more.\n\n3. Put the cookies on an action bar and eat them one after another without letting the Satisfied buff expire. The FIRST cookie gives 100%; each additional one adds 10%. Ninety-one cookies bring the buff to 1000%.\n\n4. Check the achievement at 1000%. Each cookie refreshes the buff timer, so there is no need to eat them all within one original sixty-second window. A Chef's Hat, Chocolate Cake and a special standing/sitting trick are unnecessary.",
        stepCount = 4,
        waypoints = {
            { mapID = 84, x = 0.506, y = 0.716, step = 2, label = "Stormwind sous-chef vendor - recipe and cocoa" },
            {
                mapID = 85,
                x = 0.5660000000000001,
                y = 0.626,
                step = 2,
                label = "Orgrimmar sous-chef vendor - recipe and cocoa",
            },
        },
        sources = {
            "https://www.wowhead.com/achievement=5779#comments:id=1375847",
            "https://www.wowhead.com/achievement=5779#comments:id=1401028",
            "https://www.wowhead.com/achievement=5779#comments:id=1516174",
            "https://www.wowhead.com/achievement=5779#comments:id=1623742",
        },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5779",
        sourceURL = "https://www.wowhead.com/achievement=5779#comments",
    },
}

